########## errors_auth.hurl
# Register empty username
POST {{host}}/api/users
{
  "user": {
    "username": "",
    "email": "ea_blank_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.username[0]" == "can't be blank"

# Register empty email
POST {{host}}/api/users
{
  "user": {
    "username": "ea_blank_{{uid}}",
    "email": "",
    "password": "password123"
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.email[0]" == "can't be blank"

# Register empty password
POST {{host}}/api/users
{
  "user": {
    "username": "ea_blankp_{{uid}}",
    "email": "ea_blankp_{{uid}}@test.com",
    "password": ""
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.password[0]" == "can't be blank"

# Register valid user for duplicate and login tests
POST {{host}}/api/users
{
  "user": {
    "username": "ea_dup_{{uid}}",
    "email": "ea_dup_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 201
[Captures]
token: jsonpath "$.user.token"

# Register duplicate username
POST {{host}}/api/users
{
  "user": {
    "username": "ea_dup_{{uid}}",
    "email": "ea_dup2_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 409
[Asserts]
jsonpath "$.errors.username[0]" == "has already been taken"

# Register duplicate email
POST {{host}}/api/users
{
  "user": {
    "username": "ea_dup2_{{uid}}",
    "email": "ea_dup_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 409
[Asserts]
jsonpath "$.errors.email[0]" == "has already been taken"

# Login empty email
POST {{host}}/api/users/login
{
  "user": {
    "email": "",
    "password": "password123"
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.email[0]" == "can't be blank"

# Login empty password
POST {{host}}/api/users/login
{
  "user": {
    "email": "ea_dup_{{uid}}@test.com",
    "password": ""
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.password[0]" == "can't be blank"

# Login wrong password
POST {{host}}/api/users/login
{
  "user": {
    "email": "ea_dup_{{uid}}@test.com",
    "password": "wrongpassword"
  }
}
HTTP 401
[Asserts]
jsonpath "$.errors.credentials[0]" == "invalid"

# GET /user no auth
GET {{host}}/api/user
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# PUT /user no auth
PUT {{host}}/api/user
{
  "user": {
    "bio": "test"
  }
}
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# Update email to empty string - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "email": ""
  }
}
HTTP 422

# Update username to empty string - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "username": ""
  }
}
HTTP 422

# Update email to null - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "email": null
  }
}
HTTP 422

# Update username to null - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "username": null
  }
}
HTTP 422

# === NIST 800-63B password policy for PUT /user ===
# Ref: https://pages.nist.gov/800-63-3/sp800-63b.html section 5.1.1.2
# Rules: min 8 chars, must accept at least 64 chars, no composition, no breach check (demo)

# Update password to empty string - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "password": ""
  }
}
HTTP 422

# Update password to null - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "password": null
  }
}
HTTP 422

# Update password shorter than 8 chars - should reject
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "password": "short7c"
  }
}
HTTP 422

# Update password to 8 char simple word - should accept
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "password": "bonjour1"
  }
}
HTTP 200

# Update password to 64 chars - should accept
PUT {{host}}/api/user
Authorization: Token {{token}}
{
  "user": {
    "password": "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
  }
}
HTTP 200
########## errors_articles.hurl
# Create article no auth
POST {{host}}/api/articles
{
  "article": {
    "title": "No Auth Article",
    "description": "test",
    "body": "test"
  }
}
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# GET unknown slug
GET {{host}}/api/articles/unknown-slug-{{uid}}
HTTP 404
[Asserts]
jsonpath "$.errors.article[0]" == "not found"

# Update no auth
PUT {{host}}/api/articles/some-slug
{
  "article": {
    "body": "test"
  }
}
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# Delete no auth
DELETE {{host}}/api/articles/some-slug
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# GET feed no auth
GET {{host}}/api/articles/feed
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# Favorite no auth
POST {{host}}/api/articles/some-slug/favorite
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# Unfavorite no auth
DELETE {{host}}/api/articles/some-slug/favorite
HTTP 401
[Asserts]
jsonpath "$.errors.token[0]" == "is missing"

# Setup: Register for authenticated error tests
POST {{host}}/api/users
{
  "user": {
    "username": "ea_art_{{uid}}",
    "email": "ea_art_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 201
[Captures]
token: jsonpath "$.user.token"

# Create article empty title
POST {{host}}/api/articles
Authorization: Token {{token}}
{
  "article": {
    "title": "",
    "description": "test",
    "body": "test"
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.title[0]" == "can't be blank"

# Create article empty description
POST {{host}}/api/articles
Authorization: Token {{token}}
{
  "article": {
    "title": "Err Desc {{uid}}",
    "description": "",
    "body": "test"
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.description[0]" == "can't be blank"

# Create article empty body
POST {{host}}/api/articles
Authorization: Token {{token}}
{
  "article": {
    "title": "Err Body {{uid}}",
    "description": "test",
    "body": ""
  }
}
HTTP 422
[Asserts]
jsonpath "$.errors.body[0]" == "can't be blank"

# Duplicate titles are allowed (each gets a unique slug)
POST {{host}}/api/articles
Authorization: Token {{token}}
{
  "article": {
    "title": "Dup Title {{uid}}",
    "description": "first",
    "body": "first"
  }
}
HTTP 201
[Captures]
slug1: jsonpath "$.article.slug"

POST {{host}}/api/articles
Authorization: Token {{token}}
{
  "article": {
    "title": "Dup Title {{uid}}",
    "description": "second",
    "body": "second"
  }
}
HTTP 201
[Captures]
slug2: jsonpath "$.article.slug"
[Asserts]
jsonpath "$.article.slug" != {{slug1}}

# Update unknown slug
PUT {{host}}/api/articles/unknown-slug-{{uid}}
Authorization: Token {{token}}
{
  "article": {
    "body": "test"
  }
}
HTTP 404
[Asserts]
jsonpath "$.errors.article[0]" == "not found"

# Favorite unknown slug
POST {{host}}/api/articles/unknown-slug-{{uid}}/favorite
Authorization: Token {{token}}
HTTP 404
[Asserts]
jsonpath "$.errors.article[0]" == "not found"

# Unfavorite unknown slug
DELETE {{host}}/api/articles/unknown-slug-{{uid}}/favorite
Authorization: Token {{token}}
HTTP 404
[Asserts]
jsonpath "$.errors.article[0]" == "not found"

# Update unknown slug
PUT {{host}}/api/articles/unknown-slug-{{uid}}
Authorization: Token {{token}}
{
  "article": {
    "body": "test"
  }
}
HTTP 404
[Asserts]
jsonpath "$.errors.article[0]" == "not found"

# Delete unknown slug
DELETE {{host}}/api/articles/unknown-slug-{{uid}}
Authorization: Token {{token}}
HTTP 404
[Asserts]
jsonpath "$.errors.article[0]" == "not found"

# Cleanup
DELETE {{host}}/api/articles/{{slug1}}
Authorization: Token {{token}}
HTTP 204

DELETE {{host}}/api/articles/{{slug2}}
Authorization: Token {{token}}
HTTP 204
########## errors_authorization.hurl
# Register user A
POST {{host}}/api/users
{
  "user": {
    "username": "authz_a_{{uid}}",
    "email": "authz_a_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 201
[Captures]
token_a: jsonpath "$.user.token"

# Register user B
POST {{host}}/api/users
{
  "user": {
    "username": "authz_b_{{uid}}",
    "email": "authz_b_{{uid}}@test.com",
    "password": "password123"
  }
}
HTTP 201
[Captures]
token_b: jsonpath "$.user.token"

# User A creates article
POST {{host}}/api/articles
Authorization: Token {{token_a}}
{
  "article": {
    "title": "Authz Article {{uid}}",
    "description": "test",
    "body": "test"
  }
}
HTTP 201
[Captures]
slug: jsonpath "$.article.slug"

# User B tries to delete -> 403
DELETE {{host}}/api/articles/{{slug}}
Authorization: Token {{token_b}}
HTTP 403
[Asserts]
jsonpath "$.errors.article[0]" == "forbidden"

# User B tries to update -> 403
PUT {{host}}/api/articles/{{slug}}
Authorization: Token {{token_b}}
{
  "article": {
    "body": "hijacked"
  }
}
HTTP 403
[Asserts]
jsonpath "$.errors.article[0]" == "forbidden"

# User A creates a comment on the article
POST {{host}}/api/articles/{{slug}}/comments
Authorization: Token {{token_a}}
{
  "comment": {
    "body": "A's comment"
  }
}
HTTP 201
[Captures]
comment_id: jsonpath "$.comment.id"

# User B tries to delete A's comment -> 403
DELETE {{host}}/api/articles/{{slug}}/comments/{{comment_id}}
Authorization: Token {{token_b}}
HTTP 403
[Asserts]
jsonpath "$.errors.comment[0]" == "forbidden"

# Verify comment survived the failed delete
GET {{host}}/api/articles/{{slug}}/comments
HTTP 200
[Asserts]
jsonpath "$.comments" count >= 1
jsonpath "$.comments[0].body" == "A's comment"

# Cleanup: User A deletes article
DELETE {{host}}/api/articles/{{slug}}
Authorization: Token {{token_a}}
HTTP 204
