export type ErrorBody = Record<string, string[]>

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly errors: ErrorBody,
  ) {
    super(JSON.stringify(errors))
  }
}

export const blank = (field: string) => new ApiError(422, { [field]: ["can't be blank"] })
export const taken = (field: string) => new ApiError(409, { [field]: ['has already been taken'] })
export const invalid = (field: string, msg: string) => new ApiError(422, { [field]: [msg] })
export const notFound = (entity: string) => new ApiError(404, { [entity]: ['not found'] })
export const forbidden = (entity: string) => new ApiError(403, { [entity]: ['forbidden'] })
export const tokenMissing = () => new ApiError(401, { token: ['is missing'] })
export const tokenInvalid = () => new ApiError(401, { token: ['is invalid'] })

