import { randomBytes, scryptSync, timingSafeEqual } from 'node:crypto'
import jwt from 'jsonwebtoken'
import type { FastifyReply, FastifyRequest } from 'fastify'
import { prisma } from './db.js'
import { tokenInvalid, tokenMissing } from './errors.js'

const JWT_SECRET = process.env.JWT_SECRET ?? 'realworld-dev-secret'
const KEY_LEN = 64

export function hashPassword(password: string): string {
  const salt = randomBytes(16)
  const key = scryptSync(password, salt, KEY_LEN)
  return `${salt.toString('hex')}:${key.toString('hex')}`
}

export function verifyPassword(password: string, stored: string): boolean {
  const [saltHex, keyHex] = stored.split(':')
  if (!saltHex || !keyHex) return false
  const key = Buffer.from(keyHex, 'hex')
  const candidate = scryptSync(password, Buffer.from(saltHex, 'hex'), key.length)
  return key.length === candidate.length && timingSafeEqual(key, candidate)
}

export function signToken(userId: number): string {
  return jwt.sign({ sub: String(userId) }, JWT_SECRET, { expiresIn: '30d' })
}

/** The authenticated user, as resolved by `requireAuth` / `optionalAuth`. */
export type AuthUser = { id: number; username: string; email: string; bio: string | null; image: string | null }

declare module 'fastify' {
  interface FastifyRequest {
    currentUser?: AuthUser
  }
}

/**
 * Reads `Authorization: Token <jwt>`. RealWorld clients also send `Bearer`,
 * so both prefixes are accepted.
 */
function extractToken(req: FastifyRequest): string | null {
  const header = req.headers.authorization
  if (!header) return null
  const match = /^(?:Token|Bearer)\s+(.+)$/i.exec(header.trim())
  return match ? match[1].trim() : null
}

async function resolveUser(token: string): Promise<AuthUser | null> {
  let payload: jwt.JwtPayload
  try {
    payload = jwt.verify(token, JWT_SECRET) as jwt.JwtPayload
  } catch {
    return null
  }
  const id = Number(payload.sub)
  if (!Number.isInteger(id)) return null
  return prisma.user.findUnique({
    where: { id },
    select: { id: true, username: true, email: true, bio: true, image: true },
  })
}

/** Rejects with 401 when no usable token is present. */
export async function requireAuth(req: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const token = extractToken(req)
  if (!token) throw tokenMissing()
  const user = await resolveUser(token)
  if (!user) throw tokenInvalid()
  req.currentUser = user
}

/** Attaches the user when a valid token is present, but never rejects. */
export async function optionalAuth(req: FastifyRequest, _reply: FastifyReply): Promise<void> {
  const token = extractToken(req)
  if (!token) return
  const user = await resolveUser(token)
  if (user) req.currentUser = user
}

export const currentUserId = (req: FastifyRequest): number | null => req.currentUser?.id ?? null

