import { NO_USER } from './db.js'

/**
 * Include clause shared by every article query. `favorites` and
 * `author.followers` are pre-filtered to the current user so that the
 * `favorited` / `following` flags need no extra round-trip.
 */
export const articleInclude = (viewerId: number | null) => ({
  tags: true,
  author: { include: { followers: { where: { followerId: viewerId ?? NO_USER } } } },
  favorites: { where: { userId: viewerId ?? NO_USER } },
  _count: { select: { favorites: true } },
})

export const commentInclude = (viewerId: number | null) => ({
  author: { include: { followers: { where: { followerId: viewerId ?? NO_USER } } } },
})

type UserRow = { username: string; email: string; bio: string | null; image: string | null }

export const userView = (user: UserRow, token: string) => ({
  user: {
    email: user.email,
    token,
    username: user.username,
    bio: user.bio,
    image: user.image,
  },
})

type ProfileRow = { username: string; bio: string | null; image: string | null }

export const profileView = (user: ProfileRow, following: boolean) => ({
  profile: {
    username: user.username,
    bio: user.bio,
    image: user.image,
    following,
  },
})

/* eslint-disable @typescript-eslint/no-explicit-any */
type ArticleRow = any

/**
 * `includeBody` is false for list endpoints: the spec's list responses must
 * omit the `body` key entirely rather than send it as null.
 */
export function articleView(article: ArticleRow, includeBody = true) {
  const view: Record<string, unknown> = {
    slug: article.slug,
    title: article.title,
    description: article.description,
  }
  if (includeBody) view.body = article.body
  view.tagList = article.tags.map((t: { name: string }) => t.name).sort()
  view.createdAt = article.createdAt.toISOString()
  view.updatedAt = article.updatedAt.toISOString()
  view.favorited = article.favorites.length > 0
  view.favoritesCount = article._count.favorites
  view.author = profileView(article.author, article.author.followers.length > 0).profile
  return view
}

export const commentView = (comment: ArticleRow) => ({
  id: comment.id,
  createdAt: comment.createdAt.toISOString(),
  updatedAt: comment.updatedAt.toISOString(),
  body: comment.body,
  author: profileView(comment.author, comment.author.followers.length > 0).profile,
})

