import { ApiError, blank } from './errors.js'

/** NIST 800-63B 5.1.1.2: at least 8 characters, and at least 64 must be accepted. */
export const MIN_PASSWORD_LENGTH = 8

export function asObject(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : {}
}

/** Required on create: must be a present, non-empty string. */
export function requireText(payload: Record<string, unknown>, field: string): string {
  const value = payload[field]
  if (typeof value !== 'string' || value.trim() === '') throw blank(field)
  return value
}

/**
 * Optional on update, but non-nullable: absent leaves the value untouched,
 * while null / non-string / empty is rejected.
 */
export function optionalRequiredText(payload: Record<string, unknown>, field: string): string | undefined {
  if (!(field in payload)) return undefined
  const value = payload[field]
  if (typeof value !== 'string' || value.trim() === '') throw blank(field)
  return value
}

/**
 * Optional and nullable: absent leaves the value untouched, null or empty
 * string both normalize to null.
 */
export function optionalNullableText(
  payload: Record<string, unknown>,
  field: string,
): string | null | undefined {
  if (!(field in payload)) return undefined
  const value = payload[field]
  if (value === null) return null
  if (typeof value !== 'string') throw blank(field)
  return value.trim() === '' ? null : value
}

export function optionalPassword(payload: Record<string, unknown>): string | undefined {
  if (!('password' in payload)) return undefined
  const value = payload.password
  if (typeof value !== 'string' || value === '') throw blank('password')
  if (value.length < MIN_PASSWORD_LENGTH) {
    throw new ApiError(422, { password: [`is too short (minimum is ${MIN_PASSWORD_LENGTH} characters)`] })
  }
  return value
}

/**
 * `tagList` is optional, but an explicit null is rejected; an empty array
 * clears every tag.
 */
export function optionalTagList(payload: Record<string, unknown>): string[] | undefined {
  if (!('tagList' in payload)) return undefined
  const value = payload.tagList
  if (!Array.isArray(value)) throw new ApiError(422, { tagList: ['must be an array'] })
  const tags = value.filter((t): t is string => typeof t === 'string').map((t) => t.trim()).filter(Boolean)
  return [...new Set(tags)]
}

