import type { FastifyInstance } from 'fastify'
import { prisma } from '../db.js'
import { ApiError, taken } from '../errors.js'
import { hashPassword, requireAuth, signToken, verifyPassword } from '../auth.js'
import { userView } from '../views.js'
import {
  asObject,
  optionalNullableText,
  optionalPassword,
  optionalRequiredText,
  requireText,
} from '../validation.js'

export async function userRoutes(app: FastifyInstance) {
  // POST /api/users — register
  app.post('/api/users', async (req, reply) => {
    const payload = asObject(asObject(req.body).user)
    const username = requireText(payload, 'username')
    const email = requireText(payload, 'email')
    const password = requireText(payload, 'password')

    if (await prisma.user.findUnique({ where: { username } })) throw taken('username')
    if (await prisma.user.findUnique({ where: { email } })) throw taken('email')

    const user = await prisma.user.create({
      data: { username, email, passwordHash: hashPassword(password) },
    })
    return reply.code(201).send(userView(user, signToken(user.id)))
  })

  // POST /api/users/login
  app.post('/api/users/login', async (req) => {
    const payload = asObject(asObject(req.body).user)
    const email = requireText(payload, 'email')
    const password = requireText(payload, 'password')

    const user = await prisma.user.findUnique({ where: { email } })
    if (!user || !verifyPassword(password, user.passwordHash)) {
      throw new ApiError(401, { credentials: ['invalid'] })
    }
    return userView(user, signToken(user.id))
  })

  // GET /api/user
  app.get('/api/user', { preHandler: requireAuth }, async (req) => {
    const user = req.currentUser!
    return userView(user, signToken(user.id))
  })

  // PUT /api/user
  app.put('/api/user', { preHandler: requireAuth }, async (req) => {
    const current = req.currentUser!
    const payload = asObject(asObject(req.body).user)

    const username = optionalRequiredText(payload, 'username')
    const email = optionalRequiredText(payload, 'email')
    const password = optionalPassword(payload)
    const bio = optionalNullableText(payload, 'bio')
    const image = optionalNullableText(payload, 'image')

    if (username && username !== current.username) {
      if (await prisma.user.findUnique({ where: { username } })) throw taken('username')
    }
    if (email && email !== current.email) {
      if (await prisma.user.findUnique({ where: { email } })) throw taken('email')
    }

    const user = await prisma.user.update({
      where: { id: current.id },
      data: {
        ...(username !== undefined && { username }),
        ...(email !== undefined && { email }),
        ...(password !== undefined && { passwordHash: hashPassword(password) }),
        ...(bio !== undefined && { bio }),
        ...(image !== undefined && { image }),
      },
    })
    return userView(user, signToken(user.id))
  })
}

