async function findProfile(username: string) {
  const user = await prisma.user.findUnique({ where: { username } })
  if (!user) throw notFound('profile')
  return user
}

async function isFollowing(followerId: number | null, followedId: number): Promise<boolean> {
  if (followerId === null) return false
  const link = await prisma.follow.findUnique({
    where: { followerId_followedId: { followerId, followedId } },
