import { randomBytes } from 'node:crypto'
import type { FastifyInstance } from 'fastify'
import type { Prisma } from '@prisma/client'
import { prisma } from '../db.js'
import { forbidden, notFound } from '../errors.js'
import { optionalAuth, requireAuth } from '../auth.js'
import { articleInclude, articleView } from '../views.js'
import { asObject, optionalRequiredText, optionalTagList, requireText } from '../validation.js'

const DEFAULT_LIMIT = 20

function slugify(title: string): string {
  const base = title
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80)
  // Duplicate titles are explicitly allowed, so every slug gets a random suffix.
  return `${base || 'article'}-${randomBytes(4).toString('hex')}`
}

/** Resolves tag names to ids, creating any that do not exist yet. */
async function resolveTagIds(names: string[]): Promise<number[]> {
  const ids: number[] = []
  for (const name of names) {
    const tag = await prisma.tag.upsert({ where: { name }, create: { name }, update: {} })
    ids.push(tag.id)
  }
  return ids
}

const parseIntOr = (value: unknown, fallback: number): number => {
  const parsed = Number.parseInt(String(value ?? ''), 10)
  return Number.isFinite(parsed) && parsed >= 0 ? parsed : fallback
}

export async function articleRoutes(app: FastifyInstance) {
  /** Loads an article by slug or throws the spec's 404 payload. */
  async function findArticle(slug: string, viewerId: number | null) {
    const article = await prisma.article.findUnique({
      where: { slug },
      include: articleInclude(viewerId),
    })
    if (!article) throw notFound('article')
    return article
  }

  /** Re-reads an article so the response reflects post-mutation state. */
  const reload = (id: number, viewerId: number | null) =>
    prisma.article.findUniqueOrThrow({ where: { id }, include: articleInclude(viewerId) })

  async function listResponse(where: Prisma.ArticleWhereInput, query: Record<string, unknown>, viewerId: number | null) {
    const take = parseIntOr(query.limit, DEFAULT_LIMIT)
    const skip = parseIntOr(query.offset, 0)
    const [articles, articlesCount] = await Promise.all([
      prisma.article.findMany({
        where,
        include: articleInclude(viewerId),
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        take,
        skip,
      }),
      // The spec's `articlesCount` is the total match count, not the page size.
      prisma.article.count({ where }),
    ])
    return { articles: articles.map((a) => articleView(a, false)), articlesCount }
  }

  // GET /api/articles/feed — registered before /:slug so "feed" is never a slug
  app.get('/api/articles/feed', { preHandler: requireAuth }, async (req) => {
    const viewerId = req.currentUser!.id
    const follows = await prisma.follow.findMany({
      where: { followerId: viewerId },
      select: { followedId: true },
    })
    const where: Prisma.ArticleWhereInput = { authorId: { in: follows.map((f) => f.followedId) } }
    return listResponse(where, req.query as Record<string, unknown>, viewerId)
  })

  // GET /api/articles
  app.get('/api/articles', { preHandler: optionalAuth }, async (req) => {
    const query = req.query as Record<string, unknown>
    const where: Prisma.ArticleWhereInput = {}
    if (query.tag) where.tags = { some: { name: String(query.tag) } }
    if (query.author) where.author = { username: String(query.author) }
    if (query.favorited) where.favorites = { some: { user: { username: String(query.favorited) } } }
    return listResponse(where, query, req.currentUser?.id ?? null)
  })

  // POST /api/articles
  app.post('/api/articles', { preHandler: requireAuth }, async (req, reply) => {
    const author = req.currentUser!
    const payload = asObject(asObject(req.body).article)
    const title = requireText(payload, 'title')
    const description = requireText(payload, 'description')
    const body = requireText(payload, 'body')
    const tagIds = await resolveTagIds(optionalTagList(payload) ?? [])

    const created = await prisma.article.create({
      data: {
        slug: slugify(title),
        title,
        description,
        body,
        authorId: author.id,
        tags: { connect: tagIds.map((id) => ({ id })) },
      },
    })
    return reply.code(201).send({ article: articleView(await reload(created.id, author.id)) })
  })

  // GET /api/articles/:slug
  app.get<{ Params: { slug: string } }>(
    '/api/articles/:slug',
    { preHandler: optionalAuth },
    async (req) => {
      const viewerId = req.currentUser?.id ?? null
      return { article: articleView(await findArticle(req.params.slug, viewerId)) }
    },
  )

  // PUT /api/articles/:slug
  app.put<{ Params: { slug: string } }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (req) => {
      const viewerId = req.currentUser!.id
      const article = await findArticle(req.params.slug, viewerId)
      if (article.authorId !== viewerId) throw forbidden('article')

      const payload = asObject(asObject(req.body).article)
      const title = optionalRequiredText(payload, 'title')
      const description = optionalRequiredText(payload, 'description')
      const body = optionalRequiredText(payload, 'body')
      const tagList = optionalTagList(payload)

      const data: Prisma.ArticleUpdateInput = { updatedAt: new Date() }
      if (title !== undefined) data.title = title
      if (description !== undefined) data.description = description
      if (body !== undefined) data.body = body
      if (tagList !== undefined) {
        data.tags = { set: (await resolveTagIds(tagList)).map((id) => ({ id })) }
      }

      await prisma.article.update({ where: { id: article.id }, data })
      return { article: articleView(await reload(article.id, viewerId)) }
    },
  )

  // DELETE /api/articles/:slug
  app.delete<{ Params: { slug: string } }>(
    '/api/articles/:slug',
    { preHandler: requireAuth },
    async (req, reply) => {
      const viewerId = req.currentUser!.id
      const article = await findArticle(req.params.slug, viewerId)
      if (article.authorId !== viewerId) throw forbidden('article')
      await prisma.article.delete({ where: { id: article.id } })
      return reply.code(204).send()
    },
  )

  // POST /api/articles/:slug/favorite
  app.post<{ Params: { slug: string } }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (req) => {
      const viewerId = req.currentUser!.id
      const article = await findArticle(req.params.slug, viewerId)
      await prisma.favorite.upsert({
        where: { userId_articleId: { userId: viewerId, articleId: article.id } },
        create: { userId: viewerId, articleId: article.id },
        update: {},
      })
      return { article: articleView(await reload(article.id, viewerId)) }
    },
  )

  // DELETE /api/articles/:slug/favorite
  app.delete<{ Params: { slug: string } }>(
    '/api/articles/:slug/favorite',
    { preHandler: requireAuth },
    async (req) => {
      const viewerId = req.currentUser!.id
      const article = await findArticle(req.params.slug, viewerId)
      await prisma.favorite.deleteMany({ where: { userId: viewerId, articleId: article.id } })
      return { article: articleView(await reload(article.id, viewerId)) }
    },
  )
}

