import { optionalAuth, requireAuth } from '../auth.js'
import { commentInclude, commentView } from '../views.js'
import { asObject, requireText } from '../validation.js'

async function findArticleId(slug: string): Promise<number> {
  const article = await prisma.article.findUnique({ where: { slug }, select: { id: true } })
  if (!article) throw notFound('article')
  return article.id
}

export async function commentRoutes(app: FastifyInstance) {
  // GET /api/articles/:slug/comments
  app.get<{ Params: { slug: string } }>(
    '/api/articles/:slug/comments',
    { preHandler: optionalAuth },
    async (req) => {
      const articleId = await findArticleId(req.params.slug)
      const comments = await prisma.comment.findMany({
        where: { articleId },
        include: commentInclude(req.currentUser?.id ?? null),
        orderBy: { id: 'asc' },
      })
      return { comments: comments.map(commentView) }
    },
  )

  // POST /api/articles/:slug/comments
  app.post<{ Params: { slug: string } }>(
    '/api/articles/:slug/comments',
    { preHandler: requireAuth },
    async (req, reply) => {
      const author = req.currentUser!
      const articleId = await findArticleId(req.params.slug)
      const body = requireText(asObject(asObject(req.body).comment), 'body')

      const created = await prisma.comment.create({
        data: { body, articleId, authorId: author.id },
      })
      const comment = await prisma.comment.findUniqueOrThrow({
        where: { id: created.id },
        include: commentInclude(author.id),
      })
      return reply.code(201).send({ comment: commentView(comment) })
    },
  )

  // DELETE /api/articles/:slug/comments/:id
  app.delete<{ Params: { slug: string; id: string } }>(
    '/api/articles/:slug/comments/:id',
    { preHandler: requireAuth },
    async (req, reply) => {
      const viewerId = req.currentUser!.id
      const articleId = await findArticleId(req.params.slug)
      const commentId = Number.parseInt(req.params.id, 10)
      if (!Number.isInteger(commentId)) throw notFound('comment')

      const comment = await prisma.comment.findFirst({ where: { id: commentId, articleId } })
      if (!comment) throw notFound('comment')
      if (comment.authorId !== viewerId) throw forbidden('comment')

      await prisma.comment.delete({ where: { id: comment.id } })
      return reply.code(204).send()
    },
  )
}

