import Fastify, { type FastifyInstance } from 'fastify'
import { ApiError } from './errors.js'
import { userRoutes } from './routes/users.js'
import { profileRoutes } from './routes/profiles.js'
import { articleRoutes } from './routes/articles.js'
import { commentRoutes } from './routes/comments.js'
import { tagRoutes } from './routes/tags.js'

export async function buildApp(opts: { logger?: boolean } = {}): Promise<FastifyInstance> {
  const app = Fastify({ logger: opts.logger ?? false })

  // Every error leaves through here so responses keep the RealWorld shape.
  app.setErrorHandler((error, _req, reply) => {
    if (error instanceof ApiError) {
      return reply.code(error.status).send({ errors: error.errors })
    }
    if (error.statusCode === 400) {
      return reply.code(422).send({ errors: { body: ['is invalid'] } })
    }
    reply.log.error(error)
    return reply.code(500).send({ errors: { body: ['internal server error'] } })
  })

  app.setNotFoundHandler((_req, reply) => {
    reply.code(404).send({ errors: { route: ['not found'] } })
  })

  await app.register(userRoutes)
  await app.register(profileRoutes)
  await app.register(articleRoutes)
  await app.register(commentRoutes)
  await app.register(tagRoutes)

  return app
}

